div.data-mendix-props:
"contenttype":"jsjQuery","contents":"setTimeout(function() {

 var dropdowns = document.querySelectorAll('.ESignature_EProcedure .PrefixCustomDropdown__control');

 if (dropdowns) {

 dropdowns.forEach(function(dropdown) {

 dropdown.addEventListener('mousedown', function(event) {

 setTimeout(function() {
 setDropdownPos(dropdown);
 }, 200);

 });

 });

 } else {
 console.error("Could not find dropdown to attach listener.");
 }

}, 1000);


function setDropdownPos(dropdown) {
 const rect = dropdown.getBoundingClientRect();
 const panel = document.querySelector('.ESignature_EProcedure .PrefixCustomDropdown__menu');
 const esigPanelWidth = document.querySelector('div[role=dialog]').offsetWidth * 1.5;
 const esigPanelHeight = document.querySelector('div[role=dialog]').offsetHeight * 1.5;
 const sideWidth = (window.innerWidth - esigPanelWidth) / 2;
 const sideHeight = (window.innerHeight - esigPanelHeight) / 2;

 panel.style.position = 'fixed';
 const width = (rect.left - sideWidth) / 1.5;
 const height = (rect.top - sideHeight + rect.height) / 1.5;
 panel.style.top = height + 'px';
 panel.style.left = width + 'px';
 panel.style.width = "150px";
}","contentsPath":"","onclickmf":"","documentation":"","refreshOnContextChange":false,"refreshOnContextUpdate":false,"encloseHTMLWithDiv":true
